/**
 * A Form Group lets you create a list of grouped form elements. The form elements can be radio buttons, checkboxes, text area, etc.
 *
 * - {@link https://livingdesign.walmart.com/components/form-group/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/form-group/react/ React documentation}
 *
 * ### Form Content
 *
 * Content for the form is provided through the `children` prop.
 *
 * ```tsx
 * import * as React from "react";
 * import {
 *   Checkbox,
 *   FormGroup
 * } from "@walmart-web/livingdesign-components";
 *
 * <FormGroup>
 *   <Checkbox label="Banana" />
 *   <Checkbox label="Apple" />
 *   <Checkbox label="Cookie" />
 * </FormGroup>
 * ```
 *
 * ### Label
 *
 * The Form Group accepts a text label through the `label` prop.
 *
 * ```tsx
 * import * as React from "react";
 * import {
 *   Checkbox,
 *   FormGroup
 * } from "@walmart-web/livingdesign-components";
 *
 * <FormGroup
 *   label="What monster are you?"
 * >
 *   <Checkbox label="Banana" />
 *   <Checkbox label="Apple" />
 *   <Checkbox label="Cookie" />
 * </FormGroup>
 * ```
 *
 * ### Helper Text and Error
 *
 * The Form Group accepts helper text through the `helperText` prop, or an error message through the `error` prop. (NOTE: `error` overrides `helperText`.)
 *
 * * ```tsx
 * import * as React from "react";
 * import {
 *   Checkbox,
 *   FormGroup
 * } from "@walmart-web/livingdesign-components";
 *
 * <FormGroup
 *   error="Something is wrong"
 * >
 *   <Checkbox label="Banana" />
 *   <Checkbox label="Apple" />
 *   <Checkbox label="Cookie" />
 * </FormGroup>
 * ```
 */
export declare const FormGroup: React.FunctionComponent<FormGroupProps>;
